    .filter((id) => earliest[id].finish === totalDuration)
    .map((id) => criticalTo.get(id)!);
  candidates.sort(comparePaths);

  return {
    order,
    layers,
    earliest,
    totalDuration,
    criticalPath: candidates[0] ?? [],
  };
}

